parameters.jsCode:
// Public Safety AI Agent Reasoning Engine
const complaint = $('Webhook: Receive Safety Report').first().json.body || {};
const history = $('Database: Check Repeat Hotspots').first().json || {};

const title = complaint.title || 'Public Safety Hazard';
const desc = complaint.description || '';
const textCorpus = (title + ' ' + desc).toLowerCase();
const address = complaint.location?.address || 'Municipal Zone';
const lat = complaint.location?.latitude || 28.5672;
const lng = complaint.location?.longitude || 77.1789;

// Proximity detection for sensitive infrastructure
const isNearSchool = textCorpus.includes('school') || textCorpus.includes('college') || complaint.near_school === true;
const isNearHospital = textCorpus.includes('hospital') || textCorpus.includes('clinic');
const isElectricalHazard = textCorpus.includes('electric') || textCorpus.includes('wire') || textCorpus.includes('pole') || textCorpus.includes('transformer');
const isFireOrGas = textCorpus.includes('fire') || textCorpus.includes('gas') || textCorpus.includes('smoke');
const isOpenManhole = textCorpus.includes('manhole') || textCorpus.includes('drain') || textCorpus.includes('pit');

// Determine Risk Level
let riskLevel = 'MEDIUM';
let hazardType = 'GENERAL_PUBLIC_HAZARD';

if (isElectricalHazard) {
  hazardType = 'FALLEN_ELECTRIC_POLE_LIVE_WIRES';
  riskLevel = isNearSchool || isNearHospital ? 'CRITICAL' : 'HIGH';
} else if (isFireOrGas) {
  hazardType = 'FIRE_GAS_HAZARD';
  riskLevel = 'CRITICAL';
} else if (isOpenManhole) {
  hazardType = 'OPEN_MANHOLE_PEDESTRIAN_HAZARD';
  riskLevel = 'HIGH';
}

// Recommended emergency departments (CIVIC RECOMMENDATIONS ONLY - NOT AUTONOMOUS ARMED DISPATCH)
const targetDepartments = [];
if (isElectricalHazard) targetDepartments.push('State Electricity Distribution Co. (Emergency Feeder Line)', 'Local Substation Linemen Unit');
if (isNearSchool || riskLevel === 'CRITICAL') targetDepartments.push('City Police (Traffic & Cordon Control)', 'District Disaster Management Authority (DDMA)');
if (isFireOrGas) targetDepartments.push('Fire & Rescue Services', 'Municipal Ambulance Services');
if (isOpenManhole) targetDepartments.push('Municipal Corporation Road & Drainage Dept');
if (targetDepartments.length === 0) targetDepartments.push('Municipal Civic Patrol');

// Recommended safety cordons
const safetyMeasures = [
  `Immediately isolate and restrict pedestrian and vehicular access within a 50-meter perimeter around ${address}.`,
  `Erect visible caution barriers and deploy emergency hazard blinkers.`
];

if (isNearSchool) {
  safetyMeasures.push('Coordinate with School Administration to hold students indoors or divert dismissal through alternate gates.');
}
if (isElectricalHazard) {
  safetyMeasures.push('Request Electricity Grid Operator to isolate and de-energize the local feeder line immediately.');
}

const output = {
  incident_id: 'SAF-INC-' + Date.now(),
  complaint_id: complaint.complaint_id || 'CMP-SAF-002',
  source_agent: 'public_safety_agent',
  incident_report: `Urgent hazard identified: ${title}. ${desc}. Located in proximity to sensitive public facilities (${isNearSchool ? 'School' : isNearHospital ? 'Hospital' : 'Public Thoroughfare'}). Assessed risk level: ${riskLevel}.`,
  risk_level: riskLevel,
  hazard_type: hazardType,
  location: {
    address: address,
    latitude: lat,
    longitude: lng,
    sensitive_zone: isNearSchool ? 'Government School Perimeter' : (isNearHospital ? 'Hospital Zone' : 'Residential Commercial Area')
  },
  repeated_complaints_nearby: history.matched_count || 0,
  recommended_safety_measures: safetyMeasures,
  target_departments: targetDepartments,
  escalation_status: (riskLevel === 'CRITICAL' || riskLevel === 'HIGH') ? 'IMMEDIATE_COMMAND_ESCALATION' : 'ROUTINE_DEPT_QUEUE',
  requires_urgent_notification: riskLevel === 'CRITICAL' || riskLevel === 'HIGH',
  command_alert_headline: `[PUBLIC SAFETY ALERT - ${riskLevel}] ${title} at ${address}`
};

return output;

